const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Bounding box covering the 2021 Cumbre Vieja eruption area (Todoque, El Paraíso) on La Palma.
  const aoi = ee.Geometry.Rectangle([-17.95, 28.58, -17.85, 28.65]);

  // The Cumbre Vieja eruption started on September 19, 2021.
  const beforeDateStart = '2021-05-01';
  const beforeDateEnd = '2021-05-31';
  const afterDateStart = '2021-12-01';
  const afterDateEnd = '2021-12-31';

  // 2. Data Acquisition & Processing
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  // Cloud masking function for Sentinel-2
  const maskS2clouds = function(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
                   qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
        .select("B2", "B3", "B4", "B8", "B11", "B12")
        .copyProperties(image, ["system:time_start"]);
  };

  // Function to identify lava flows. Fresh lava is dark (low reflectance).
  // A threshold on the Blue band (B2) and SWIR1 (B11) is effective.
  // We use Blue because it's less affected by vegetation shadows than red/NIR.
  // We use SWIR1 as it also shows very low reflectance for lava.
  const classifyLava = function(image) {
      const isLava = image.select('B2').lt(0.05).and(image.select('B11').lt(0.15));
      return isLava.selfMask();
  };

  // --- BEFORE PERIOD ---
  let beforeCollection = s2Collection
      .filterBounds(aoi)
      .filterDate(beforeDateStart, beforeDateEnd)
      .map(maskS2clouds);

  if (beforeCollection.size().getInfo() === 0) {
      console.log('Evidence: No cloud-free images found for the "before" period (May 2021).');
      console.log("C1");
      return;
  }

  const beforeImage = beforeCollection.median();
  const beforeLava = classifyLava(beforeImage);

  // --- AFTER PERIOD ---
  let afterCollection = s2Collection
      .filterBounds(aoi)
      .filterDate(afterDateStart, afterDateEnd)
      .map(maskS2clouds);

  if (afterCollection.size().getInfo() === 0) {
      console.log('Evidence: No cloud-free images found for the "after" period (Dec 2021).');
      console.log("C1");
      return;
  }

  const afterImage = afterCollection.median();
  const afterLava = classifyLava(afterImage);

  // 3. Calculation
  const pixelArea = ee.Image.pixelArea(); // Area in m^2 per pixel
  const scale = 30; // Use a reasonable scale

  // Calculate area of lava before the eruption
  const beforeLavaArea = beforeLava.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
  });

  // Calculate area of lava after the eruption
  const afterLavaArea = afterLava.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
  });

  // Await results
  const beforeAreaSqKm = ee.Number(beforeLavaArea.get('B2')).divide(1e6).getInfo();
  const afterAreaSqKm = ee.Number(afterLavaArea.get('B2')).divide(1e6).getInfo();

  // 4. Validation & Final Answer
  console.log(`Evidence: Number of images found (Before): ${beforeCollection.size().getInfo()}`);
  console.log(`Evidence: Number of images found (After): ${afterCollection.size().getInfo()}`);

  if (beforeAreaSqKm === null || afterAreaSqKm === null) {
      console.log('Evidence: Failed to calculate area for one or both periods.');
      console.log("C3");
      return;
  }

  const areaIncrease = afterAreaSqKm - beforeAreaSqKm;
  const areaIncreaseThreshold = 1; // A threshold of 1 sq km increase to be significant

  console.log(`Evidence: Estimated lava flow area before (May 2021): ${beforeAreaSqKm.toFixed(2)} sq km`);
  console.log(`Evidence: Estimated lava flow area after (Dec 2021): ${afterAreaSqKm.toFixed(2)} sq km`);
  console.log(`Evidence: Increase in lava flow area: ${areaIncrease.toFixed(2)} sq km`);

  if (areaIncrease > areaIncreaseThreshold) {
      console.log("A");
  } else {
      console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
